// src/assets/icons.ts — inlined icons so the extension works offline.
// Generated by scripts/inline-icons.mjs; do not edit by hand. Run the script to regenerate.

export const LOGO_PNG = "data:image/png;base64,"

/** Test-only signing key (not a secret; the real one comes from the environment). */
export const TEST_SIGNING_KEY = ""

export function iconUrl(name: string): string {
  // decode lazily: most pages never show the logo
  return name === "logo" ? LOGO_PNG : `/icons/${name}.svg`
}
